        height = len(input_grid)
        width = len(input_grid[0])
        output_grid = [[0 for _ in range(3)] for _ in range(height)]
        one_column_index = -1
        for x in range(width):
            if all(input_grid[y][x] == 1 for y in range(height)):
                one_column_index = x
                break
        if one_column_index == -1:
            return output_grid
        for y in range(height):
            for x in range(min(one_column_index, 3)):
                input_value = input_grid[y][one_column_index - 1 - x]
                if input_value == 9:
                    output_grid[y][2 - x] = 0
                elif input_value == 0:
                    output_grid[y][2 - x] = 8
        return output_grid

    return transform(task.test[0].input)

